_RAD_COLOR_PROPS = ("BackColor", "ForeColor")
_RAD_INT_PROPS = ("Left", "Top", "Width", "Height", "FontSize", "Value")


def _rad_rgb_hex(value):
    """'#rgb' / '#rrggbb' -> (r, g, b) or None."""
    s = str(value or "").strip()
    if not s.startswith("#"):
        return None
    s = s[1:]
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    try:
        return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4)) if len(s) >= 6 else None
    except ValueError:
        return None


def _rad_ease(f, ease):
    if ease == "in":
        return f * f
    if ease == "out":
        return 1 - (1 - f) * (1 - f)
    if ease == "inout":
        return 2 * f * f if f < 0.5 else 1 - 2 * (1 - f) * (1 - f)
    if ease == "sine":
        return -(_math.cos(_math.pi * f) - 1) / 2
    if ease == "back":                              # overshoots a little, then settles
        return 1 + 2.70158 * (f - 1) ** 3 + 1.70158 * (f - 1) ** 2
    if ease == "elastic":
        if f <= 0 or f >= 1:
            return 1.0 if f >= 1 else 0.0
        return 2 ** (-10 * f) * _math.sin((f * 10 - 0.75) * (2 * _math.pi / 3)) + 1
    if ease == "bounce":
        n, d = 7.5625, 2.75
        if f < 1 / d:
            return n * f * f
        if f < 2 / d:
            f -= 1.5 / d
            return n * f * f + 0.75
        if f < 2.5 / d:
            f -= 2.25 / d
            return n * f * f + 0.9375
        f -= 2.625 / d
        return n * f * f + 0.984375
    return f


class _RadText(str):
    """Text being typed (typewriter keyframes): mixes by the length of the common prefix."""


def _rad_mix(prop, a, b, f, rgb):
    """Value of property *prop* between a (f = 0) and b (f = 1); rgb(colour) -> (r, g, b).
    Numbers follow f beyond 1 (back / elastic easings overshoot); colours and text stop at b."""
    if f <= 0:
        return a
    if prop in _RAD_COLOR_PROPS:
        if f >= 1:
            return b
        ca, cb = rgb(a), rgb(b)
        if ca is None or cb is None:
            return a
        return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(x + (y - x) * f)))) for x, y in zip(ca, cb))
    if isinstance(a, bool) or isinstance(b, bool):
        return b if f >= 1 else a
    if isinstance(a, _RadText) or isinstance(b, _RadText):
        sa, sb = str(a or ""), str(b or "")
        if sa.startswith(sb) or sb.startswith(sa):
            longer = sa if len(sa) > len(sb) else sb
            n = len(sa) + (len(sb) - len(sa)) * min(f, 1.0)
            return _RadText(longer[:max(0, int(round(n)))])
        return b if f >= 1 else a
    try:
        x, y = float(a), float(b)
    except (TypeError, ValueError):
        return b if f >= 1 else a                  # Text...: discrete keyframes
    v = x + (y - x) * f
    return int(round(v)) if prop in _RAD_INT_PROPS else v


def _rad_resolve(prop, v, start, ref=None):
    """A keyframe value made absolute against *start* (the value when the animation starts):
    {"d": n} start + n, {"m": k} start * k, {"of": "Width", "f": x} start + x * start Width,
    {"reveal": 0..1} the start text up to that fraction, "$parent" the parent's background colour;
    ref(prop) = start value of another property of the same control (ref("$parent") = parent colour)."""
    if isinstance(v, str) and v == "$parent":
        c = ref("$parent") if ref is not None else None
        return c if c else start
    if not isinstance(v, dict):
        return v
    if "reveal" in v:
        s = "" if start is None else str(start)
        try:
            f = max(0.0, min(1.0, float(v["reveal"])))
        except (TypeError, ValueError):
            f = 1.0
        return _RadText(s[:int(round(len(s) * f))])
    if isinstance(start, bool) or start is None:
        return start
    try:
        x = float(start)
    except (TypeError, ValueError):
        return start                               # colours / text: relative keys keep the start value
    try:
        val = x * float(v.get("m", 1)) + float(v.get("d", 0))
        if v.get("of"):
            other = ref(str(v["of"])) if ref is not None else None
            val += float(v.get("f", 0)) * float(other if other is not None else 0)
    except (TypeError, ValueError):
        return start
    if prop in _RAD_INT_PROPS:
        return int(round(val))
    return max(0.0, min(1.0, val)) if prop == "Opacity" else val


def _rad_resolve_keys(prop, keys, start, ref=None):
    """Keyframes [(ms, value, ease)] with relative values made absolute (see _rad_resolve)."""
    return [(k[0], _rad_resolve(prop, k[1], start, ref)) + tuple(k[2:]) for k in keys]


def _rad_has_relative(keys):
    return any(isinstance(k[1], dict) or (isinstance(k[1], str) and k[1] == "$parent") for k in keys)


def _rad_value_at(prop, keys, t, start, rgb):
    """keys = [(ms, value, ease), ...] sorted by time; start = value before the first key."""
    if not keys:
        return start
    pts = list(keys)
    if pts[0][0] > 0 and start is not None:
        pts.insert(0, (0, start, ""))
    if t <= pts[0][0]:
        return pts[0][1]
    for (t0, v0, _e0), (t1, v1, e1) in zip(pts, pts[1:]):
        if t <= t1:
            f = (t - t0) / (t1 - t0) if t1 > t0 else 1.0
            return _rad_mix(prop, v0, v1, _rad_ease(f, e1), rgb)
    return pts[-1][1]


class _RadStateEvents(QObject):
    """Feeds MouseOver / Pressed / Focused / Disabled of one widget to the visual state manager."""

    def __init__(self, widget, name, vsm):
        super().__init__(widget)
        self.w, self.name, self.vsm = widget, name, vsm
        self.map = {QEvent.Type.Enter: ("MouseOver", True), QEvent.Type.Leave: ("MouseOver", False),
                    QEvent.Type.MouseButtonPress: ("Pressed", True),
                    QEvent.Type.MouseButtonRelease: ("Pressed", False),
                    QEvent.Type.FocusIn: ("Focused", True), QEvent.Type.FocusOut: ("Focused", False)}
        widget.installEventFilter(self)
        vp = getattr(widget, "viewport", None)
        if callable(vp):
            vp().installEventFilter(self)
        if not widget.isEnabled():
            vsm.Flag(name, "Disabled", True)

    def eventFilter(self, obj, ev):
        t = ev.type()
        if t == QEvent.Type.EnabledChange and obj is self.w:
            self.vsm.Flag(self.name, "Disabled", not self.w.isEnabled())
        elif t in self.map:
            state, on = self.map[t]
            self.vsm.Flag(self.name, state, on)
        return False


class _RadFxEvents(QObject):
    """Click / mouse enter / leave of one widget starts an animation (Animations window triggers)."""

    def __init__(self, widget, event, fn):
        super().__init__(widget)
        self.w, self.fn = widget, fn
        self.t = {"click": QEvent.Type.MouseButtonRelease, "enter": QEvent.Type.Enter,
                  "leave": QEvent.Type.Leave}[event]
        widget.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.w and ev.type() == self.t:
            inside = True
            if self.t == QEvent.Type.MouseButtonRelease:
                try:
                    inside = self.w.rect().contains(ev.position().toPoint())
                except AttributeError:
                    pass
            if inside:
                self.fn()
        return False


class _RadIO:
    """Reads / writes neutral properties of the Qt widgets (visual states, storyboards, bindings)."""
    vis_hook = None         # animations: callable(name, visible) -> True when it handles the change
    quiet = 0               # > 0 while the animations write (no show / hide hooks)

    def __init__(self, owner):
        self.o = owner
        self._colors, self._base_ss, self._events = {}, {}, []

    def w(self, name):
        return self.o if not name else getattr(self.o, name)

    def get(self, name, prop):
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    return w.windowTitle()
                if isinstance(w, QPlainTextEdit):
                    return w.toPlainText()
                if isinstance(w, QGroupBox):
                    return w.title()
                if isinstance(w, QComboBox):
                    return w.currentText()
                return w.text() if hasattr(w, "text") else ""
            if prop == "Left":
                return w.x()
            if prop == "Top":
                return w.y()
            if prop == "Width":
                return w.width()
            if prop == "Height":
                return w.height() - self._top() if not name else w.height()
            if prop in ("BackColor", "ForeColor"):
                return self._colors.get(name, {}).get(prop, "")
            if prop == "Visible":
                return not w.isHidden()
            if prop == "FontSize":
                return w.font().pointSize()
            if prop == "FontBold":
                return w.font().bold()
            if prop == "FontItalic":
                return w.font().italic()
            if prop == "Opacity":
                if not name:
                    return w.windowOpacity()
                eff = w.graphicsEffect()
                return eff.opacity() if isinstance(eff, QGraphicsOpacityEffect) else 1.0
            if prop == "Value":
                return w.value()
            if prop == "Checked":
                return w.isChecked()
        except (AttributeError, RuntimeError, TypeError):
            return None
        return None

    def _top(self):
        client = self.o.__dict__.get("_client")
        return self.o.height() - client.height() if client is not None else 0

    @staticmethod
    def _hold(name, w, prop):
        """A state / storyboard sets this geometry: Anchor / Dock leave it alone until release()."""
        if name:
            held = getattr(w, "_rad_held", None)
            if held is None:
                held = set()
                w._rad_held = held
            held.add(prop)

    def release(self, name, prop=None):
        """A state / storyboard gave the geometry back: Anchor / Dock place the control again."""
        if not name:
            return
        try:
            w = self.w(name)
            held = getattr(w, "_rad_held", None)
            if not held:
                return
            if prop is None:
                held.clear()
            else:
                held.discard(prop)
            host = w.parentWidget()
            for lay in (host.children() if host is not None else []):
                if type(lay).__name__ == "_Layout" and any(it[0] is w for it in lay.items):
                    lay.apply()
        except (AttributeError, RuntimeError):
            pass

    def set(self, name, prop, v):
        if v is None:
            return
        if prop == "Visible" and name and not self.quiet and self.vis_hook is not None \
                and self.vis_hook(name, bool(v)):
            return                                  # an "On show" / "On hide" animation takes over
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    w.setWindowTitle(str(v))
                elif isinstance(w, QPlainTextEdit):
                    w.setPlainText(str(v))
                elif isinstance(w, QGroupBox):
                    w.setTitle(str(v))
                elif isinstance(w, QComboBox):
                    if w.isEditable():
                        w.setEditText(str(v))
                    elif w.findText(str(v)) >= 0:
                        w.setCurrentIndex(w.findText(str(v)))
                elif hasattr(w, "setText"):
                    w.setText(str(v))
            elif prop in ("Left", "Top"):
                self._hold(name, w, prop)
                w.move(int(v) if prop == "Left" else w.x(), int(v) if prop == "Top" else w.y())
            elif prop in ("Width", "Height"):
                self._hold(name, w, prop)
                top = 0 if name else self._top()
                w.resize(int(v) if prop == "Width" else w.width(), int(v) + top if prop == "Height" else w.height())
            elif prop in ("BackColor", "ForeColor"):
                d = self._colors.setdefault(name, {})
                if v:
                    d[prop] = str(v)
                else:
                    d.pop(prop, None)
                self._restyle(name, w)
            elif prop == "Visible":
                w.setVisible(bool(v))
            elif prop in ("FontSize", "FontBold", "FontItalic"):
                f = w.font()
                if prop == "FontSize":
                    f.setPointSize(max(1, int(v)))
                elif prop == "FontBold":
                    f.setBold(bool(v))
                else:
                    f.setItalic(bool(v))
                w.setFont(f)
            elif prop == "Opacity":
                if not name:
                    w.setWindowOpacity(float(v))
                else:
                    eff = w.graphicsEffect()
                    if not isinstance(eff, QGraphicsOpacityEffect):
                        eff = QGraphicsOpacityEffect(w)
                        w.setGraphicsEffect(eff)
                    eff.setOpacity(max(0.0, min(1.0, float(v))))
            elif prop == "Value":
                w.setValue(int(float(v)))
            elif prop == "Checked":
                w.setChecked(bool(v))
        except (AttributeError, RuntimeError, TypeError, ValueError):
            pass

    def _restyle(self, name, w):
        if name not in self._base_ss:
            self._base_ss[name] = w.styleSheet()
        d = self._colors.get(name, {})
        rules = ""
        if d.get("BackColor"):
            rules += f"background-color:{d['BackColor']};"
        if d.get("ForeColor"):
            rules += f"color:{d['ForeColor']};"
        if not rules:
            w.setStyleSheet(self._base_ss[name])
            return
        if not w.objectName():
            w.setObjectName(name or "rad_form")
        sel = f"#{w.objectName()}" + (", #client" if not name else "")
        w.setStyleSheet(self._base_ss[name] + f"\n{sel} {{ {rules} }}")

    def set_items(self, name, items):
        w = self.w(name)
        w.clear()
        w.addItems([str(i) for i in items])

    def set_rows(self, name, columns, rows):
        w = self.w(name)
        w.clear()
        w.setColumnCount(max(1, len(columns)))
        w.setHorizontalHeaderLabels([str(c) for c in columns])
        w.setRowCount(len(rows))
        for r, row in enumerate(rows):
            for c, text in enumerate(row):
                w.setItem(r, c, QTableWidgetItem(str(text)))

    def rgb(self, name, prop, value):
        c = _rad_rgb_hex(value)
        if c is not None:
            return c
        if value:
            q = QColor(str(value))
        else:
            w = self.w(name)
            q = w.palette().color(w.backgroundRole() if prop == "BackColor" else w.foregroundRole())
        return (q.red(), q.green(), q.blue()) if q.isValid() else None

    def later(self, ms, fn):
        QTimer.singleShot(int(ms), self.o, fn)

    def bind(self, name, event, fn):
        """Animation triggers: event "click" / "enter" / "leave" of a control ("" = the form) calls fn()."""
        self._events.append(_RadFxEvents(self.w(name), event, fn))

    def parent_bg(self, name):
        try:
            w = self.w(name)
            host = w.parentWidget() or w
            return host.palette().color(host.backgroundRole()).name()
        except (AttributeError, RuntimeError):
            return None

    def on_select(self, name, fn):
        w = self.w(name)
        sig = w.currentRowChanged if isinstance(w, QListWidget) else w.currentIndexChanged
        sig.connect(lambda i: i >= 0 and fn(i))

    def hook(self, name, vsm, disabled=False):
        self._events.append(_RadStateEvents(self.w(name), name, vsm))


def _rad_vposture(v):
    """Any posture spelling -> flat | half-opened | folded ("" = unknown)."""
    s = str(v or "").strip().lower().replace("-", "").replace("_", "").replace(" ", "")
    if s in ("halfopened", "halfopen", "half", "tabletop", "book"):
        return "half-opened"
    if s in ("folded", "closed", "fold", "cover"):
        return "folded"
    if s in ("flat", "open", "opened"):
        return "flat"
    return ""


def _rad_vmatch(when, w, h, orientation=None, posture=None, span=None, fold=None):
    """True when every condition of a layout size's "when" holds for a client area of w x h."""
    if not isinstance(when, dict):
        return False
    for k, v in when.items():
        if v is None or v == "":
            continue
        if k in ("minWidth", "maxWidth", "minHeight", "maxHeight"):
            try:
                lim = float(v)
            except (TypeError, ValueError):
                return False
            val = w if k.endswith("Width") else h
            if (val < lim) if k.startswith("min") else (val > lim):
                return False
        elif k == "orientation":
            if str(v).strip().lower()[:4] != (orientation or ("landscape" if w > h else "portrait"))[:4]:
                return False
        elif k == "posture":
            if _rad_vposture(v) != _rad_vposture(posture):
                return False
        elif k == "span":
            if str(v).strip().lower() != (span or "single"):
                return False
        elif k == "fold":
            if str(v).strip().lower() != str(fold or "").lower():
                return False
    return True


def _rad_vmatching(sizes, w, h, orientation=None, posture=None, span=None, fold=None):
    """Ids of the sizes that apply, in list order (later ones win, like CSS)."""
    return [s["id"] for s in sizes if _rad_vmatch(s.get("when"), w, h, orientation, posture, span, fold)]


def _rad_venv():
    """Posture / span / fold of a simulated foldable (RADIDE_POSTURE, RADIDE_SPAN, RADIDE_HINGE=x,y,w,h)."""
    import os
    env = os.environ
    posture = _rad_vposture(env.get("RADIDE_POSTURE", ""))
    span = str(env.get("RADIDE_SPAN", "") or "").strip().lower()
    span = "dual" if span in ("dual", "2", "spanned") else ("single" if span else "")
    hinge, fold = None, ""
    try:
        parts = [int(float(p)) for p in str(env.get("RADIDE_HINGE", "")).split(",") if p.strip()]
        if len(parts) == 4:
            hinge = tuple(parts)
    except ValueError:
        pass
    if hinge is not None and posture != "folded":
        fold = "vertical" if hinge[2] <= hinge[3] else "horizontal"
    if not span:
        span = "dual" if posture == "half-opened" or (hinge is not None and posture != "folded"
                                                      and min(hinge[2], hinge[3]) > 0) else "single"
    return {"posture": posture, "span": span, "hinge": hinge, "fold": fold}


class _RadVariants:
    """Layout variants: the sizes designed with "This size only" follow the window (CSS-like cascade)."""

    def __init__(self, owner, io, plan, form_name, tk=True):
        self.o, self.io, self.plan, self.form_name, self.tk = owner, io, plan, form_name, tk
        self.current = None
        self.env = _rad_venv()
        self.places = {}
        self._hosts = {}
        keys = {}
        for ctl in plan["controls"].values():
            for n, e in ctl.items():
                keys.setdefault(n, set()).update(e.get("props") or {})
        # the designed values, read back from the widgets (restored when a size stops applying)
        self._base_props = {n: {k: io.get(n, k) for k in ks} for n, ks in keys.items()
                            if getattr(owner, n, None) is not None}
        fks = {k for fo in plan["form"].values() for k in fo}
        self._base_form = {k: io.get("", k) for k in fks}
        self.base = {n: tuple(s) for n, s in plan["base"].items() if getattr(owner, n, None) is not None}
        self._attach()
        self.update()

    # ------------------------------------------------------------ toolkit
    def _top(self):
        client = self.o.__dict__.get("_client")
        if client is not None:
            return client
        return self.o.root if self.tk else self.o

    def size(self):
        h = self._top()
        try:
            return (h.winfo_width(), h.winfo_height()) if self.tk else (h.width(), h.height())
        except Exception:  # noqa: BLE001 - the window is being destroyed
            return 0, 0

    def _attach(self):
        if self.tk:
            self._top().bind("<Configure>", self._configured, add="+")
        else:
            self._watch(self._top())

    def _configured(self, e):
        if e.widget is self._top():
            self.update()

    def _watch(self, host):
        if host is None or id(host) in self._hosts:
            return
        self._hosts[id(host)] = _RadVariantEvents(self, host)

    def _place(self, name, spec):
        w = getattr(self.o, name, None)
        if w is None:
            return
        self.places[name] = spec
        x, y, ww, hh, rx, ry, rw, rh = spec
        if self.tk:
            opts = {"x": x, "y": y, "width": ww, "height": hh, "relx": rx, "rely": ry, "relwidth": rw,
                    "relheight": rh}
            self.o._places.setdefault(name, {}).update(opts)
            try:
                if w.winfo_manager() == "place":
                    w.place_configure(**opts)
            except Exception:  # noqa: BLE001
                pass
            return
        host = w.parentWidget()
        self._watch(host)
        for lay in (host.children() if host is not None else []):
            items = getattr(lay, "items", None)
            if type(lay).__name__ == "_Layout" and items:      # Anchor / Dock: this control is ours now
                lay.items = [it for it in items if it[0] is not w]
        self._geo(w, spec)

    def _geo(self, w, spec):
        host = w.parentWidget()
        if host is None:
            return
        cw, ch = host.width(), host.height()
        x, y, ww, hh, rx, ry, rw, rh = spec
        g = [round(x + rx * cw), round(y + ry * ch), max(0, round(ww + rw * cw)), max(0, round(hh + rh * ch))]
        held = getattr(w, "_rad_held", None)        # geometry a visual state / storyboard is animating
        if held:
            for i, (prop, cur) in enumerate((("Left", w.x()), ("Top", w.y()), ("Width", w.width()),
                                             ("Height", w.height()))):
                if prop in held:
                    g[i] = cur
        w.setGeometry(*g)

    def relayout(self, host):
        for name, spec in self.places.items():
            w = getattr(self.o, name, None)
            if w is not None and w.parentWidget() is host:
                self._geo(w, spec)

    # ------------------------------------------------------------ sizes
    def update(self, *_a):
        """Re-checks which sizes apply; True when they changed."""
        w, h = self.size()
        if w <= 1 or h <= 1:                        # not mapped yet: the designed size
            w, h = self.plan["design"]
        e = self.env
        ids = _rad_vmatching(self.plan["sizes"], w, h, None, e["posture"], e["span"], e["fold"])
        if ids == self.current:
            return False
        first = self.current is None
        self.current = ids
        self._apply(ids)
        if not first:
            fn = getattr(self.o, self.form_name + "_SizeVariantChanged", None)
            if fn is not None:
                fn()
        return True

    def _apply(self, ids):
        p = self.plan
        props = {n: dict(v) for n, v in self._base_props.items()}
        places = dict(self.base)
        fprops = dict(self._base_form)
        for vid in ids:
            for n, e in p["controls"].get(vid, {}).items():
                if n in props:
                    props[n].update(e.get("props") or {})
                if e.get("place") is not None and n in places:
                    places[n] = tuple(e["place"])
            fprops.update(p["form"].get(vid) or {})
        io = self.io
        io.quiet = getattr(io, "quiet", 0) + 1      # no "On show" / "On hide" animations for a size change
        try:
            for k, v in fprops.items():
                io.set("", k, v)
            for n, spec in places.items():
                self._place(n, spec)
            for n, pr in props.items():
                for k, v in pr.items():
                    if k != "Visible":
                        io.set(n, k, v)
                if "Visible" in pr:
                    io.set(n, "Visible", pr["Visible"])
        finally:
            io.quiet -= 1


class _RadVariantEvents(QObject):
    """Layout variants: a container was resized - re-place the controls of the current sizes."""

    def __init__(self, rv, host):
        super().__init__(host)
        self.rv, self.host = rv, host
        host.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.host and ev.type() == QEvent.Type.Resize:
            if obj is self.rv._top():
                self.rv.update()
            self.rv.relayout(obj)
        return False


